pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 value, bytes calldata calldataArg) public {
        Reverter reverter = new Reverter();
        vm.deal(address(c), value);
        address target = address(reverter);
        bool ok;
        try c.sendMoney(target, value, calldataArg) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
